(1139476, 139641, 23583, '<td valign="top">Very creative idea.  I''m curious about how you did this without a double exposure. :)</td>', 'Very creative idea.  I''m curious about how you did this without a double exposure. :)', '2005-01-29 21:13:50.000000', NULL, 1),
(1139478, 139623, 32608, '<td valign="top">creative angle on a common theme.</td>', 'creative angle on a common theme.', '2005-01-29 21:16:14.000000', NULL, 1),
