(1139483, 139998, 32608, '<td valign="top">great idea could have been a littler sharper focus</td>', 'great idea could have been a littler sharper focus', '2005-01-29 21:22:01.000000', NULL, 1),
(1139484, 139568, 31720, '<td valign="top">Two things that would make this picture better (in my opinion (well, of course it''s my opinion... just take this as you will)): (1) The tilt of the phones are distracting, especially being so close to the edge of the photo that it makes a strange angle. (2) Rotate the phones so that they face the negative space so it doesn''t seem like a bad crop job.</td>', 'Two things that would make this picture better (in my opinion (well, of course it''s my opinion... just take this as you will)): (1) The tilt of the phones are distracting, especially being so close to the edge of the photo that it makes a strange angle. (2) Rotate the phones so that they face the negative space so it doesn''t seem like a bad crop job.', '2005-01-29 21:22:07.000000', NULL, 1),
(1139487, 138497, 32608, '<td valign="top">I see your shutter was right around 1 sec</td>', 'I see your shutter was right around 1 sec', '2005-01-29 21:24:20.000000', NULL, 1),
