INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1140913, 138972, 32570, '<td valign="top">Love this idea - I wish I could see the "size" of the memory stick.  I think it would add to the contrast.  (it could be a 32MB or it could be a 1GB - huge contrast difference.)</td>', 'Love this idea - I wish I could see the "size" of the memory stick.  I think it would add to the contrast.  (it could be a 32MB or it could be a 1GB - huge contrast difference.)', '2005-01-30 21:55:09.000000', NULL, 1),
(1140914, 139749, 32570, '<td valign="top">My Favorite in this contest.  Fantastic shot.  It actually took me a second to see the windmills and then the picture was perfect!  Well Done.</td>', 'My Favorite in this contest.  Fantastic shot.  It actually took me a second to see the windmills and then the picture was perfect!  Well Done.', '2005-01-30 21:55:51.000000', NULL, 1),
(1140917, 139641, 32570, '<td valign="top">isn''t this  a double exposure?</td>', 'isn''t this  a double exposure?', '2005-01-30 21:56:37.000000', NULL, 1),
(1140918, 139944, 32070, '<td valign="top">very inspired...</td>', 'very inspired...', '2005-01-30 21:56:44.000000', NULL, 1),
(1140923, 139756, 32570, '<td valign="top">This shot would be great for any contest.  Very nicely done.  The contrast between old and new is so strong here.  I really like this.</td>', 'This shot would be great for any contest.  Very nicely done.  The contrast between old and new is so strong here.  I really like this.', '2005-01-30 21:58:28.000000', NULL, 1),
(1140927, 139969, 32570, '<td valign="top">This is a brilliant idea, but not enough contrast.  An 8mb card vs a 1 or 2GB card and this would have been perfect.  Excellent idea nonetheless.</td>', 'This is a brilliant idea, but not enough contrast.  An 8mb card vs a 1 or 2GB card and this would have been perfect.  Excellent idea nonetheless.', '2005-01-30 21:59:38.000000', NULL, 1),
(1140932, 138120, 32570, '<td valign="top">I think this would have worked better if you had either JUST the mowers, or perhaps a younger person behind the new mower.  The dog adds nothing to the shot.</td>', 'I think this would have worked better if you had either JUST the mowers, or perhaps a younger person behind the new mower.  The dog adds nothing to the shot.', '2005-01-30 22:02:03.000000', NULL, 1),
(1140933, 139739, 32570, '<td valign="top">Great contrast and excellent choice for the background.  Well done.</td>', 'Great contrast and excellent choice for the background.  Well done.', '2005-01-30 22:02:39.000000', NULL, 1),
(1140936, 139556, 32570, '<td valign="top">Excellent work.  The idea and execution is fantastic, although I think you''ve taken the rule of thirds a little far.  Nevertheless - great work.</td>', 'Excellent work.  The idea and execution is fantastic, although I think you''ve taken the rule of thirds a little far.  Nevertheless - great work.', '2005-01-30 22:04:11.000000', NULL, 1),
(1140940, 139975, 32570, '<td valign="top">LOVE IT!  The title really makes the photo that much better.  Great job!</td>', 'LOVE IT!  The title really makes the photo that much better.  Great job!', '2005-01-30 22:06:06.000000', NULL, 1),
(1140942, 139600, 32570, '<td valign="top">a little less "shocking" background and I think this shot would have been perfect.</td>', 'a little less "shocking" background and I think this shot would have been perfect.', '2005-01-30 22:07:53.000000', NULL, 1),
(1140943, 139871, 32672, '<td valign="top">Reminds me of childhood.</td>', 'Reminds me of childhood.', '2005-01-30 22:08:12.000000', NULL, 1),
(1140946, 139823, 32672, '<td valign="top">Focused on all the right parts.</td>', 'Focused on all the right parts.', '2005-01-30 22:09:21.000000', NULL, 1),
(1140947, 138835, 32672, '<td valign="top">Followes rule of thirds well</td>', 'Followes rule of thirds well', '2005-01-30 22:09:59.000000', NULL, 1),
(1140950, 139976, 32570, '<td valign="top">Great work!  This is not only an excellent idea, but fantastic execution.  Well done.</td>', 'Great work!  This is not only an excellent idea, but fantastic execution.  Well done.', '2005-01-30 22:11:15.000000', NULL, 1),
