(1465705, 139213, 15711, '<td valign="top">Tres bien!!!</td>', 'Tres bien!!!', '2005-06-18 19:47:24.000000', NULL, 0),
(1492920, 139858, 37719, '<td valign="top">Wasn''t a member when this challenge was run, but I think this fits perfectly with your style.  I like that you did it in black and white too.  Adds to the effect of the disparity in size between the two snakes.  I found the foreground a little distracting but my eye was definitely drawn to the snakes heads.  Sometimes DoF can play tricks on perception for the viewer that the photographer doesn''t see.  Overall nice image.  I just wonder how you got them to ''pose'' for this shot.  Everytime I have tried to shoot a snake it never works.  They just won''t sit still.  Nice job. Would have given it a 7 or 8 first round and probably bumped it up.<br/><br/><i>Message edited by author 2005-06-29 18:38:42.</i></td>', 'Wasn''t a member when this challenge was run, but I think this fits perfectly with your style.  I like that you did it in black and white too.  Adds to the effect of the disparity in size between the two snakes.  I found the foreground a little distracting but my eye was definitely drawn to the snakes heads.  Sometimes DoF can play tricks on perception for the viewer that the photographer doesn''t see.  Overall nice image.  I just wonder how you got them to ''pose'' for this shot.  Everytime I have tried to shoot a snake it never works.  They just won''t sit still.  Nice job. Would have given it a 7 or 8 first round and probably bumped it up.', '2005-06-29 19:38:08.000000', '2005-06-29 19:38:42.000000', 0),
(1569831, 138837, 14476, '<td valign="top">Oh, there''s a story here, for sure.  Wonder how much pressure it took to get that unusual house in the foreground preserved.  The architects did a good job working around it.  Nice one.</td>', 'Oh, there''s a story here, for sure.  Wonder how much pressure it took to get that unusual house in the foreground preserved.  The architects did a good job working around it.  Nice one.', '2005-07-28 12:45:14.000000', NULL, 0),
(1581294, 138837, 32754, '<td valign="top">This is a good shot!  The tree on right could be cloned out, but I guess you had a basic edit in this challenge...good detail and color</td>', 'This is a good shot!  The tree on right could be cloned out, but I guess you had a basic edit in this challenge...good detail and color', '2005-08-02 20:31:42.000000', NULL, 0),
(1789454, 139749, 35517, '<td valign="top">oh wow david...this is just gorgeous.. can''t belive it didn''t ribbon... top shot...</td>', 'oh wow david...this is just gorgeous.. can''t belive it didn''t ribbon... top shot...', '2005-10-17 05:22:47.000000', NULL, 0),
(2332319, 139556, 24715, '<td valign="top">Ha, another tube! Cool!</td>', 'Ha, another tube! Cool!', '2006-04-21 10:30:10.000000', NULL, 0),
(2360465, 139542, 22970, '<td valign="top">Wonderfully done with your selective desaturation. A very nice way of introducing new into old. The trees up top look like they are moving in the wind, which gives the photograph motion. Great job!</td>', 'Wonderfully done with your selective desaturation. A very nice way of introducing new into old. The trees up top look like they are moving in the wind, which gives the photograph motion. Great job!', '2006-04-30 00:57:54.000000', NULL, 0),
(2489436, 138505, 2780, '<td valign="top">Check out that hair! :P</td>', 'Check out that hair! :P', '2006-06-06 08:26:54.000000', NULL, 0),
(4624866, 139923, 33769, '<td valign="top">Beautiful image! that reminds me i want to get into town and take some shots of the unicorn statues! --i love the effect of the buildings curving over the statehouse... it really gives the feeling that they''re ''looming over''</td>', 'Beautiful image! that reminds me i want to get into town and take some shots of the unicorn statues! --i love the effect of the buildings curving over the statehouse... it really gives the feeling that they''re ''looming over''', '2008-04-08 22:32:20.000000', NULL, 0);
